."},{"id":"s2","texto":"Como el desmonte es afuera, no es asunto de la reserva."},{"id":"s3","texto":"Controlaremos perros sueltos y caza con patrullajes."},{"id":"s4","texto":"Hay 69 especies amenazadas en la reserva."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen diagnóstico lee bien los datos y actúa sobre lo que más pesa.","por_opcion":{"s2":"Afecta al 70 % de las especies: trabajar con los vecinos es prioritario.","s4":"Se revisaron 40 especies; 69 es la suma de amenazas, no de especies."}}}]}]}$ac$::jsonb);
